mapper.update:
update svc_package
category_id = #{categoryId}, code = #{code}, name = #{name}, description = #{description}, image = #{image}, price = #{price}, original_price = #{originalPrice}, valid_days = #{validDays}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select p.id, p.category_id, p.name, p.description, p.price, p.original_price, p.valid_days, p.status
from svc_package p

    and p.name like concat('%', #{name}, '%')
    and p.category_id = #{categoryId}
    and p.status = #{status}

order by p.id desc
